-- PSU Pulse schema for XAMPP (MariaDB). Generated by scripts/export_schema.py
-- Safe to import more than once: existing tables and data are left untouched.
CREATE DATABASE IF NOT EXISTS `psupulse` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `psupulse`;

CREATE TABLE IF NOT EXISTS feedback_windows (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	label VARCHAR(120) NOT NULL, 
	week_number INTEGER NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	opened_at DATETIME, 
	closed_at DATETIME, 
	processed_at DATETIME, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_feedback_windows_start_date` ON `feedback_windows` (`start_date`);
CREATE INDEX IF NOT EXISTS `ix_feedback_windows_status` ON `feedback_windows` (`status`);

CREATE TABLE IF NOT EXISTS settings (
	`key` VARCHAR(64) NOT NULL, 
	value VARCHAR(255) NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS units (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	code VARCHAR(30) NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	unit_type VARCHAR(20) NOT NULL, 
	parent_id INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(parent_id) REFERENCES units (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_units_unit_type` ON `units` (`unit_type`);

CREATE TABLE IF NOT EXISTS users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	username VARCHAR(64) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	email VARCHAR(120), 
	password_hash VARCHAR(255) NOT NULL, 
	`role` VARCHAR(20) NOT NULL, 
	active BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	last_login DATETIME, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_users_role` ON `users` (`role`);
CREATE UNIQUE INDEX IF NOT EXISTS `ix_users_username` ON `users` (`username`);

CREATE TABLE IF NOT EXISTS access_logs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER, 
	action VARCHAR(50) NOT NULL, 
	target VARCHAR(200), 
	ip_address VARCHAR(45), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_access_logs_created_at` ON `access_logs` (`created_at`);
CREATE INDEX IF NOT EXISTS `ix_access_logs_user_id` ON `access_logs` (`user_id`);

CREATE TABLE IF NOT EXISTS alerts (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	window_id INTEGER NOT NULL, 
	unit_id INTEGER, 
	alert_type VARCHAR(30) NOT NULL, 
	severity VARCHAR(10) NOT NULL, 
	topic VARCHAR(40), 
	metric FLOAT, 
	message VARCHAR(255) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	action_notes TEXT, 
	public_note BOOL NOT NULL, 
	handled_by_id INTEGER, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(window_id) REFERENCES feedback_windows (id) ON DELETE CASCADE, 
	FOREIGN KEY(unit_id) REFERENCES units (id) ON DELETE CASCADE, 
	FOREIGN KEY(handled_by_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_alerts_severity` ON `alerts` (`severity`);
CREATE INDEX IF NOT EXISTS `ix_alerts_status` ON `alerts` (`status`);
CREATE INDEX IF NOT EXISTS `ix_alerts_unit_id` ON `alerts` (`unit_id`);
CREATE INDEX IF NOT EXISTS `ix_alerts_window_id` ON `alerts` (`window_id`);

CREATE TABLE IF NOT EXISTS change_logs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER, 
	category VARCHAR(30) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	reason TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_change_logs_created_at` ON `change_logs` (`created_at`);

CREATE TABLE IF NOT EXISTS feedback (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	window_id INTEGER NOT NULL, 
	unit_id INTEGER NOT NULL, 
	text TEXT NOT NULL, 
	pii_redacted BOOL NOT NULL, 
	submitted_on DATE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(window_id) REFERENCES feedback_windows (id) ON DELETE CASCADE, 
	FOREIGN KEY(unit_id) REFERENCES units (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_feedback_unit_id` ON `feedback` (`unit_id`);
CREATE INDEX IF NOT EXISTS `ix_feedback_window_id` ON `feedback` (`window_id`);

CREATE TABLE IF NOT EXISTS reports (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	window_id INTEGER NOT NULL, 
	generated_by_id INTEGER, 
	generated_at DATETIME NOT NULL, 
	summary_json LONGTEXT NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (window_id), 
	FOREIGN KEY(window_id) REFERENCES feedback_windows (id) ON DELETE CASCADE, 
	FOREIGN KEY(generated_by_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS submission_tokens (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	window_id INTEGER NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	created_on DATE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(window_id) REFERENCES feedback_windows (id) ON DELETE CASCADE, 
	UNIQUE (token_hash)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_submission_tokens_window_id` ON `submission_tokens` (`window_id`);

CREATE TABLE IF NOT EXISTS user_units (
	user_id INTEGER NOT NULL, 
	unit_id INTEGER NOT NULL, 
	PRIMARY KEY (user_id, unit_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(unit_id) REFERENCES units (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS weekly_aggregates (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	window_id INTEGER NOT NULL, 
	unit_id INTEGER, 
	total INTEGER NOT NULL, 
	positive INTEGER NOT NULL, 
	negative INTEGER NOT NULL, 
	neutral INTEGER NOT NULL, 
	avg_score FLOAT NOT NULL, 
	positive_share FLOAT NOT NULL, 
	negative_share FLOAT NOT NULL, 
	neutral_share FLOAT NOT NULL, 
	delta_negative_share FLOAT, 
	delta_avg_score FLOAT, 
	topics_json TEXT, 
	keywords_json TEXT, 
	computed_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_aggregate_window_unit UNIQUE (window_id, unit_id), 
	FOREIGN KEY(window_id) REFERENCES feedback_windows (id) ON DELETE CASCADE, 
	FOREIGN KEY(unit_id) REFERENCES units (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_weekly_aggregates_unit_id` ON `weekly_aggregates` (`unit_id`);
CREATE INDEX IF NOT EXISTS `ix_weekly_aggregates_window_id` ON `weekly_aggregates` (`window_id`);

CREATE TABLE IF NOT EXISTS sentiment_results (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	feedback_id INTEGER NOT NULL, 
	label VARCHAR(10) NOT NULL, 
	score FLOAT NOT NULL, 
	confidence FLOAT NOT NULL, 
	positive_score FLOAT NOT NULL, 
	negative_score FLOAT NOT NULL, 
	topic VARCHAR(40) NOT NULL, 
	topics_json TEXT, 
	keywords_json TEXT, 
	analyzer_version VARCHAR(40) NOT NULL, 
	analyzed_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (feedback_id), 
	FOREIGN KEY(feedback_id) REFERENCES feedback (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX IF NOT EXISTS `ix_sentiment_results_label` ON `sentiment_results` (`label`);
CREATE INDEX IF NOT EXISTS `ix_sentiment_results_topic` ON `sentiment_results` (`topic`);

